    enonce: "بيّن أنّ: <span dir=\"ltr\" class=\"expr\">E = a + b + 10</span> حيث <span dir=\"ltr\" class=\"expr\">E = -(1 - a) + 4 - [-b - (1 - a)] - (-6 - a)</span>",
    correction: [{"quoi":"نرفع القوس الأول","math":"<span dir=\"ltr\" class=\"expr\">-(1 - a) = -1 + a</span>"},{"quoi":"نرفع القوس المربّع","math":"<span dir=\"ltr\" class=\"expr\">- [-b - (1 - a)] = b + 1 - a</span>"},{"quoi":"نرفع القوس الأخير","math":"<span dir=\"ltr\" class=\"expr\">- (-6 - a) = 6 + a</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">E = -1 + a + 4 + b + 1 - a + 6 + a</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">E = (a - a + a) + b + (-1 + 4 + 1 + 6)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-1 + 4 + 1 + 6 = 10</span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">E = a + b + 10</span>"}],
