    correction: [{"quoi":"نرفع القوس الداخلي","math":"<span dir=\"ltr\" class=\"expr\">- (1 - a) = -1 + a</span>"},{"quoi":"نرفع القوس المربّع","math":"<span dir=\"ltr\" class=\"expr\">- [-4 - 1 + a - b] = 4 + 1 - a + b</span>"},{"quoi":"نرفع القوس الأخير","math":"<span dir=\"ltr\" class=\"expr\">- (b - 9) = -b + 9</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">F = -b + 4 + 1 - a + b - b + 9</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">F = -a + (-b + b - b) + (4 + 1 + 9)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">4 + 1 + 9 = 14</span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">F = -a - b + 14</span>"}],
