    correction: [{"quoi":"نبسّط Z","math":"<span dir=\"ltr\" class=\"expr\">Z = 20 - 1 + m</span>"},{"quoi":"نبسّط T","math":"<span dir=\"ltr\" class=\"expr\">T = -23 + n + 1</span>"},{"quoi":"نحسب الفرق","math":"<span dir=\"ltr\" class=\"expr\">Z - T = (m - n) + (20 - 1 + 23 - 1)</span>"},{"quoi":"نعوّض بالمعطى","math":"<span dir=\"ltr\" class=\"expr\">Z - T = (-29) + 41</span>"},{"quoi":"نحسب","math":"<span dir=\"ltr\" class=\"expr\">Z - T = 12</span>"},{"quoi":"نحدّد إشارة الفرق","math":"<span dir=\"ltr\" class=\"expr\">12 &gt; 0</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">Z &gt; T</span>"}],
